  /* Card text. what = 2 sentences, why = 2–3 sentences, how = 3–5 bullets. */
  var C = {
  /* ---------- L8 People & Governance ---------- */
  "Users": { what: "Users are the staff, citizens and customers who log in and use your systems. Every request a system handles starts with someone’s intent.", why: "Most attacks start by tricking or impersonating a user rather than breaking technology. A single stolen password or a mistaken click can give an attacker the same access that person has.", how: ["Give people only the access their role needs.", "Use phishing-resistant multi-factor authentication (MFA) for every account.", "Make secure behaviour easy, and make it easy to report mistakes without blame.", "Train people in short, regular, role-based sessions."], ncsc: ["s_eng", "caf_b6", "s_iam"], nist: ["n50"] },
  "Admins": { what: "Admins are the people who run systems and infrastructure, with powers ordinary users do not have. They can change settings, create accounts and read most data.", why: "An admin account is the most valuable target in any organisation. If an attacker controls one, they can switch off defences, steal data and cover their tracks.", how: ["Use separate admin accounts that are never used for email or web browsing.", "Require phishing-resistant MFA and dedicated, hardened admin devices.", "Give admin rights just in time and remove them when the job is done.", "Log and review everything admins do."], ncsc: ["ssa", "ssa_tier", "caf_b2"], nist: ["n53"] },
  "Suppliers": { what: "Suppliers are third parties that provide your services, software or staff and may have access to your systems, code or data. They are part of your attack surface.", why: "Attackers often break into a smaller supplier to reach the bigger organisation behind it. A supplier with weak security can bypass your own controls through trusted access.", how: ["Know which suppliers have access to what.", "Set security requirements in contracts and check they are met.", "Give suppliers time-limited, monitored and least-privilege access.", "Plan what you will do if a supplier is compromised."], ncsc: ["supply_p", "caf_a4", "s_supply"], nist: ["n161"] },
  "JML process": { what: "Joiners, movers and leavers (JML) is the process for giving, changing and removing people’s access as they start, change role or leave. It is usually shared by HR, managers and IT.", why: "Access tends to build up when people move roles, and accounts are often left active after people leave. Old or excessive access is an easy route in for attackers and insiders.", how: ["Link account creation and removal to HR records.", "Remove access on the day someone leaves.", "Review access whenever someone changes role.", "Check regularly for accounts with no owner."], ncsc: ["s_iam", "caf_b2", "ce_uac"], nist: ["n53"] },
  "ISO/IEC 27001": { what: "ISO/IEC 27001 is an international standard for running an information security management system. It sets out how to find risks, choose controls and keep improving.", why: "Without a management system, security work tends to be patchy and depends on a few people. A recognised framework gives structure, accountability and evidence that others can trust.", how: ["Define the scope and get visible leadership support.", "Carry out risk assessments and record why controls were chosen.", "Run internal audits and management reviews on a regular cycle.", "Use certification as evidence, not as the goal itself."], ncsc: ["risk", "caf_a1", "caf_a2"], nist: ["csf"] },
  "NCSC CAF": { what: "The Cyber Assessment Framework (CAF) is the NCSC’s outcome-based framework for checking how well important services are protected. It is grouped into four objectives covering risk, protection, detection and response.", why: "Organisations that run important services need a consistent way to measure cyber resilience. The CAF focuses on outcomes, so it works whatever technology is in use.", how: ["Map your essential functions and the systems that support them.", "Assess yourself against each CAF principle and outcome.", "Turn the gaps into an improvement plan with named owners.", "Re-assess regularly and track progress."], ncsc: ["caf_intro", "caf", "caf_a1"], nist: ["csf"] },
  "Secure by Design": { what: "Secure by Design is a UK government approach to building security into digital services from the start of delivery. It treats security as a shared responsibility across the whole team.", why: "Adding security at the end is costly and often leaves gaps. Designing it in from the start lowers risk and avoids expensive rework.", how: ["Name a senior person responsible for security from the start.", "Use threat modelling early in design.", "Choose secure defaults and well-supported components.", "Test security throughout delivery and in live service."], ncsc: ["gov_sbd", "design", "dev"], nist: ["n160", "n218"] },
  "SABSA": { what: "SABSA is a framework for designing security architecture from business needs. It links each security control back to a business goal and risk.", why: "Security that is not tied to business goals tends to be either too weak or too costly. Tracing controls to risks helps justify spending and avoids gaps.", how: ["Start with business goals and what could stop them.", "Turn those into security requirements, then into design choices.", "Keep a clear link from each control back to the risk it treats.", "Review the architecture as the business changes."], ncsc: ["design", "antipat", "risk"], nist: ["n160"] },
  "Awareness": { what: "Security awareness is ongoing, role-based education that helps people spot and avoid threats. Good programmes measure whether behaviour actually changes.", why: "People are targeted every day by phishing, scams and social engineering. Without awareness, one person’s mistake can lead to a serious breach.", how: ["Keep training short, regular and relevant to each role.", "Focus on real threats such as phishing and payment fraud.", "Reward reporting and never shame people for mistakes.", "Measure reporting rates, not just course completion."], ncsc: ["s_eng", "caf_b6", "phish"], nist: ["n50"] },
  "Phish reporting": { what: "Phish reporting combines practice phishing emails with an easy way for people to report suspicious messages. It turns staff into an early-warning system.", why: "Some phishing will always reach inboxes. Fast reports let the security team remove a campaign before more people fall for it.", how: ["Add a one-click report button to email.", "Send reports straight to the team that can act on them.", "Thank reporters and tell them the outcome.", "Use simulations to learn and improve, not to punish."], ncsc: ["phish", "phish_scams", "caf_c1"], nist: ["n50"] },
  "Vetting": { what: "Vetting checks that people are who they say they are and are suitable for the access they will have. In the UK it ranges from baseline checks to national security vetting levels.", why: "Access to sensitive systems or information depends on trusting the person. Checks reduce the risk of fraud, coercion or insider harm.", how: ["Set the level of checks by the access the role needs.", "Complete checks before giving access.", "Re-check when roles or risks change.", "Keep vetting records secure and limited to those who need them."], ncsc: ["gov_bpss", "gov_vet", "caf_b6"], nist: ["n53"] },
  "Access reviews": { what: "Access reviews are regular checks that people still need the access they have. Managers or system owners confirm or remove each right.", why: "Access builds up over time as people move roles and projects end. Unused access is a free route for attackers and insiders.", how: ["Review privileged and sensitive access most often.", "Make the reviewer someone who understands the role.", "Remove access that is not confirmed, by default.", "Remove leavers’ access quickly and check it is gone."], ncsc: ["s_iam", "caf_b2", "ce_uac"], nist: ["n53"] },
  "Duty separation": { what: "Separation of duties means no single person can complete a sensitive action alone. For example, one person requests a payment and another approves it.", why: "One person with complete control can make a costly mistake or commit fraud without anyone noticing. Splitting the task means a second person can spot problems.", how: ["Identify high-risk actions such as payments and admin changes.", "Require a second approver for them.", "Stop the same account from both requesting and approving.", "Review exceptions regularly."], ncsc: ["ssa_tier", "caf_b2"], nist: ["n53"] },
  "Insider risk": { what: "An insider risk programme looks for and handles harm caused, on purpose or by accident, by people with legitimate access. HR, security and line managers work on it together.", why: "Insiders already have access, so outside defences do not stop them. Early signs are often seen by colleagues or HR before any technical alert.", how: ["Set clear rules and explain how monitoring is used.", "Bring HR, legal and security together to handle concerns.", "Limit and log access to sensitive data.", "Support staff under pressure, which is a common trigger."], ncsc: ["caf_b2", "caf_c1", "s_data"], nist: ["n53"] },
  "IR exercises": { what: "Incident response exercises are rehearsals of how you would handle a real cyber incident. They test playbooks, decisions and communications before a crisis.", why: "Plans that have never been tested usually fail under pressure. Exercises show gaps in contacts, decisions and backups while it is still safe to fix them.", how: ["Run short tabletop exercises with leaders and technical teams.", "Base scenarios on likely threats such as ransomware.", "Include communications, legal and suppliers.", "Record lessons and update the plan afterwards."], ncsc: ["exbox", "caf_d1", "caf_d2"], nist: ["n61"] },
  "Risk ownership": { what: "Risk ownership means every significant cyber risk has a named senior owner. The board sets how much risk the organisation will accept.", why: "Risks without owners are not managed and often grow unseen. Clear owners make sure decisions and spending match the real level of risk.", how: ["Keep a risk register with a named owner for each risk.", "Agree a risk appetite at board level.", "Report the main cyber risks to the board regularly.", "Record decisions to accept, treat or transfer each risk."], ncsc: ["board", "caf_a1", "s_risk"], nist: ["n39", "n30"] },
  "Helpdesk ID checks": { what: "Helpdesk identity checks confirm who someone is before resetting their password or MFA. They stop attackers who phone the helpdesk pretending to be staff.", why: "Attackers increasingly call helpdesks to get MFA reset on a target’s account. A convincing caller can bypass strong authentication in minutes.", how: ["Use strong checks such as a video call or a manager confirming.", "Never rely only on facts an attacker could find online.", "Apply extra checks for admin and senior staff accounts.", "Alert the account owner whenever MFA is reset."], ncsc: ["mfa", "authpol", "caf_b2"], nist: ["n63a", "n63b"] },

  /* ---------- L7 Application ---------- */
  "HTTP/S": { what: "HTTP is the language web browsers and apps use to talk to web servers. HTTPS is the same thing protected by TLS encryption.", why: "Plain HTTP can be read and changed by anyone on the network path. Web apps are also the most attacked part of most organisations.", how: ["Use HTTPS everywhere and redirect HTTP to HTTPS.", "Turn on HSTS so browsers always use HTTPS.", "Keep web servers and frameworks patched.", "Put internet-facing apps behind a web application firewall."], ncsc: ["tls", "cloud_if", "ce_sc"], nist: ["n52", "n44"] },
  "DNS": { what: "DNS turns names like www.example.com into the numeric addresses computers use. Almost every connection starts with a DNS lookup.", why: "If DNS is hijacked or poisoned, users can be sent to fake sites without noticing. Attackers also use DNS to smuggle data out and to reach malicious domains.", how: ["Use a protective DNS service that blocks known bad domains.", "Lock your domain registrar account with MFA.", "Sign your zones with DNSSEC where you can.", "Log DNS queries and look for unusual patterns."], ncsc: ["pdns", "pdns_priv", "caf_c1"], nist: ["n81"] },
  "SMTP": { what: "SMTP is the protocol that moves email between mail servers. It is also used when your email app sends a message.", why: "SMTP was designed without checks on who the sender really is, which makes spoofing easy. Mail can also travel without encryption unless you require it.", how: ["Publish SPF, DKIM and DMARC records for your domains.", "Require TLS between mail servers (MTA-STS).", "Use a secure email gateway to filter phishing and malware.", "Never allow an open relay."], ncsc: ["email", "email_tx", "email_mtasts"], nist: ["n177", "n45"] },
  "IMAP/POP3": { what: "IMAP and POP3 are the protocols email apps use to fetch messages from a mailbox. IMAP keeps mail on the server, while POP3 usually downloads it.", why: "Older set-ups send passwords in plain text and often skip MFA. Attackers use them for password spraying and to read mailboxes.", how: ["Only allow the encrypted versions (IMAPS 993, POP3S 995).", "Turn off legacy, basic authentication and use modern sign-in with MFA.", "Turn off IMAP and POP3 for people who do not need them.", "Watch for unusual sign-ins to mailboxes."], ncsc: ["email_tx", "mfa", "authpol"], nist: ["n177"] },
  "FTP": { what: "FTP is an old protocol for transferring files between computers. It sends usernames, passwords and files in clear text.", why: "Anyone who can see the traffic can steal FTP passwords and files. Exposed FTP servers are often found and abused by attackers.", how: ["Replace FTP with SFTP or FTPS.", "Never allow anonymous upload to an internet-facing server.", "Limit which addresses can connect.", "Retire FTP servers that are no longer needed."], ncsc: ["tls", "ce_sc", "cloud_tx"], nist: ["n53"] },
  "SSH": { what: "SSH (Secure Shell) is an encrypted way to log in to and manage servers and network devices remotely. It is also used for secure file transfer and tunnels.", why: "SSH often gives full control of a system, so stolen keys or weak passwords are very valuable to attackers. Exposed SSH services are scanned constantly.", how: ["Use key-based or certificate login, not passwords.", "Do not expose SSH directly to the internet; use a bastion or VPN.", "Turn off root login and keep SSH software patched.", "Track and rotate SSH keys, and remove old ones."], ncsc: ["ssa_if", "ssa", "caf_b2"], nist: ["ir7966"] },
  "SNMP": { what: "SNMP is used to monitor and manage network devices such as routers, switches and printers. It can read settings and sometimes change them.", why: "Older versions use simple shared passwords (community strings) sent in clear text. With write access, an attacker can reconfigure network devices.", how: ["Use SNMPv3 with authentication and encryption.", "Turn off SNMPv1 and v2c, and change default community strings.", "Allow SNMP only from management systems.", "Use read-only access unless write is truly needed."], ncsc: ["ssa_if", "ce_sc", "caf_b4"], nist: ["n53"] },
  "LDAP": { what: "LDAP is the protocol used to look up and manage users, groups and devices in a directory such as Active Directory. Many apps use it to check logins.", why: "Directories hold the keys to the whole organisation. Unencrypted LDAP can leak passwords, and attackers query it to map out targets.", how: ["Use LDAPS or LDAP signing and channel binding.", "Do not expose directory services to the internet.", "Limit anonymous access and what each account can read.", "Watch for unusual or bulk directory queries."], ncsc: ["caf_b2", "s_iam", "tls"], nist: ["n53"] },
  "DHCP": { what: "DHCP automatically gives devices an IP address and network settings when they join a network. It also tells them which DNS servers and gateway to use.", why: "A rogue DHCP server can send devices to an attacker’s DNS or gateway. That lets the attacker watch or redirect traffic.", how: ["Turn on DHCP snooping on switches.", "Allow DHCP replies only from trusted ports.", "Monitor for unexpected DHCP servers.", "Use 802.1X so only known devices join the network."], ncsc: ["netfund", "caf_b5"], nist: ["n53"] },
  "NTP": { what: "NTP keeps the clocks on computers and devices in step. Accurate time is needed for logs, certificates and logins such as Kerberos.", why: "If time is wrong or tampered with, logins can fail and logs cannot be matched up during an investigation. Badly configured NTP servers can also be abused for DDoS attacks.", how: ["Use a small set of trusted, internal time sources.", "Use authenticated NTP or NTS where supported.", "Block NTP management queries from the internet.", "Alert if device clocks drift."], ncsc: ["logging", "caf_c1"], nist: ["n53"] },
  "RDP": { what: "Remote Desktop Protocol (RDP) lets someone see and control a Windows desktop or server from another computer. It is widely used for remote admin and support.", why: "RDP exposed to the internet is one of the most common ways ransomware gangs get in. Weak passwords and unpatched RDP services are quickly found and abused.", how: ["Never expose RDP directly to the internet.", "Put RDP behind a VPN, gateway or ZTNA with MFA.", "Turn on Network Level Authentication and keep systems patched.", "Lock out repeated failed logins and monitor access."], ncsc: ["ssa_if", "malware", "ce_fw"], nist: ["n46"] },
  "Kerberos": { what: "Kerberos is the ticket-based login system behind Active Directory. After you sign in once, it gives you tickets to reach other services.", why: "Attackers steal or forge tickets to move around a network without passwords (for example pass-the-ticket and Golden Ticket attacks). Weak service account passwords can also be cracked offline.", how: ["Use long, random passwords or managed accounts for services.", "Turn off old encryption types such as RC4.", "Protect domain controllers as your most critical systems.", "Monitor for unusual ticket requests."], ncsc: ["caf_b2", "lateral", "ssa_tier"], nist: ["n53"] },
  "SIP": { what: "SIP sets up, manages and ends voice and video calls over IP networks. It is the signalling behind most VoIP phone systems.", why: "Exposed SIP systems are abused for toll fraud, which can run up large phone bills quickly. Unencrypted calls can also be listened to or redirected.", how: ["Use encrypted SIP (TLS on 5061) and SRTP for media.", "Put a session border controller at the edge.", "Use strong passwords on phones and admin portals.", "Watch for unusual call patterns such as international calls at night."], ncsc: ["tls", "netfund", "caf_b4"], nist: ["n58"] },
  "MQTT": { what: "MQTT is a lightweight messaging protocol used by IoT and sensor devices to send and receive data. Devices publish messages to a central broker.", why: "Many brokers are left open on the internet with no login, exposing data and control of devices. Fake messages can trigger real-world actions in buildings or plants.", how: ["Require login and use TLS (port 8883).", "Give each device its own credentials and limited topics.", "Do not expose brokers directly to the internet.", "Keep broker software patched."], ncsc: ["places", "ot", "tls"], nist: ["n213"] },
  "WAF": { what: "A web application firewall (WAF) sits in front of a website or API and filters harmful web requests. It blocks common attacks such as SQL injection and cross-site scripting.", why: "Web apps are exposed to the whole internet and often have flaws. A WAF reduces risk while fixes are made and blocks a lot of automated attacks.", how: ["Put all internet-facing web apps and APIs behind a WAF.", "Start in detect mode, tune, then switch to block.", "Keep rule sets up to date.", "Still fix the code; a WAF is a safety net, not a cure."], ncsc: ["cloud_if", "caf_b4", "apis"], nist: ["n44"] },
  "API gateway": { what: "An API gateway is the front door for an organisation’s APIs. It checks who is calling, what they are allowed to do and how often.", why: "APIs expose data and functions directly, and broken access checks are a common cause of data leaks. A gateway applies the same protections to every API.", how: ["Require authentication and authorisation on every API call.", "Validate requests against a schema.", "Apply rate limits and quotas.", "Log calls and alert on unusual use."], ncsc: ["apis", "cloud_if", "zt_pol"], nist: ["n228", "n204"] },
  "IAM · SSO · MFA": { what: "Identity and access management (IAM) controls who can sign in and what they can reach. Single sign-on (SSO) gives one login across apps, and MFA adds a second proof such as a passkey.", why: "Stolen passwords are behind a large share of breaches. Central identity with strong MFA stops most password-based attacks and makes removing access quick.", how: ["Connect all apps to one identity provider using SSO.", "Use phishing-resistant MFA such as passkeys or FIDO2 keys.", "Block legacy sign-in methods that skip MFA.", "Use conditional access based on device and risk."], ncsc: ["mfa", "authpol", "ce_uac"], nist: ["n63b"] },
  "PAM": { what: "Privileged access management (PAM) protects and controls powerful admin accounts. It stores admin passwords, gives rights only when needed and records sessions.", why: "Admin accounts are the main target for attackers because they unlock everything. PAM limits how long those powers exist and makes misuse visible.", how: ["Put all admin and service account passwords in a vault.", "Give admin rights just in time with approval.", "Record and review privileged sessions.", "Rotate passwords automatically after use."], ncsc: ["ssa_pam", "ssa", "caf_b2"], nist: ["n53"] },
  "SPF · DKIM · DMARC": { what: "SPF, DKIM and DMARC are DNS records that prove which servers may send email for your domain. Receiving mail servers use them to reject fake messages.", why: "Without them, anyone can send email that appears to come from your domain. That is a common route for phishing and invoice fraud.", how: ["Publish an SPF record listing your real senders.", "Sign outgoing mail with DKIM.", "Start DMARC at p=none, review the reports, then move to reject.", "Protect domains that never send email with a reject policy."], ncsc: ["email", "email_spf", "email_dmarc"], nist: ["n177"] },
  "Protective DNS": { what: "Protective DNS is a DNS service that refuses to look up known malicious domains. It blocks connections to malware, phishing and command servers.", why: "Most malware and phishing needs a DNS lookup to work. Blocking bad domains stops many attacks early and gives useful alerts.", how: ["Point all devices and resolvers at a protective DNS service.", "Stop devices from bypassing it with other DNS servers.", "Review blocked lookups as possible signs of infection.", "Turn on DNSSEC validation."], ncsc: ["pdns", "pdns_priv", "heightened"], nist: ["n81"] },
  "SWG / CASB": { what: "A secure web gateway (SWG) checks and filters web traffic. A cloud access security broker (CASB) sees and controls how cloud apps are used.", why: "Staff reach thousands of websites and cloud services that can deliver malware or leak data. These tools give visibility and control without blocking the useful web.", how: ["Send web traffic from all devices through the gateway, including remote users.", "Block known bad and high-risk categories.", "Find unapproved cloud apps and decide which to allow.", "Apply data rules to approved cloud apps."], ncsc: ["browser", "saas", "zt_net"], nist: ["n53"] },
  "DLP": { what: "Data loss prevention (DLP) looks at content in email, files and web traffic to spot sensitive data leaving the organisation. It can warn, block or log.", why: "Personal and sensitive data can leak by mistake or on purpose. DLP catches it before it leaves and shows where data is going.", how: ["Find and label your most sensitive data first.", "Start with alerts and user prompts before blocking.", "Cover email, endpoints, cloud apps and the web.", "Review alerts and refine rules regularly."], ncsc: ["s_data", "caf_b3", "bulk"], nist: ["n53"] },
  "EDR / AV": { what: "Endpoint detection and response (EDR) and antivirus protect laptops and servers. They block known malware and spot suspicious behaviour so it can be stopped.", why: "Endpoints are where malware runs and where attackers work. EDR shows what happened and lets teams isolate a device quickly.", how: ["Install it on every laptop and server, and check coverage.", "Keep it updated and protected against tampering.", "Make sure someone watches and acts on alerts.", "Practise isolating a device."], ncsc: ["av", "malware", "ce_mal"], nist: ["n53"] },
  "SAST · DAST · SCA": { what: "These are automated security tests for software. SAST checks source code, DAST tests a running app, and SCA checks third-party libraries for known flaws.", why: "Most applications are built from your code plus many open-source parts. Finding flaws before release is much cheaper and safer than after an attack.", how: ["Run SAST and SCA on every code change.", "Run DAST against test environments before release.", "Fix the most serious findings before shipping.", "Keep a software bill of materials (SBOM)."], ncsc: ["dev_test", "dev_pipe", "supply_sw"], nist: ["n218", "n115"] },
  "RASP": { what: "Runtime application self-protection (RASP) is security built into a running application. It watches how the app behaves and can block attacks from inside.", why: "Some attacks only show up inside the app, where perimeter tools cannot see. RASP adds protection for high-value apps that cannot be fixed quickly.", how: ["Use it for high-risk or legacy applications.", "Test performance impact before going live.", "Start in monitor mode, then turn on blocking.", "Send alerts to your monitoring team."], ncsc: ["caf_b4", "dev", "d_detect"], nist: ["n53"] },
  "Secrets vault": { what: "A secrets vault stores passwords, keys and tokens securely and hands them to apps when needed. It can also rotate them automatically.", why: "Secrets hard-coded in code or config files are often leaked through code repositories. Once found, they give direct access to systems and data.", how: ["Move secrets out of code and config into a vault.", "Give each app only the secrets it needs.", "Rotate secrets regularly and after any suspected leak.", "Scan code repositories for secrets."], ncsc: ["kms", "dev_repo", "caf_b3"], nist: ["n57"] },

  /* ---------- L6 Presentation ---------- */
  "TLS/SSL": { what: "TLS encrypts data moving between two systems and proves the server is genuine. SSL was its older version and is no longer safe.", why: "Without TLS, passwords and data can be read or changed in transit. Old versions and weak settings can be broken or downgraded.", how: ["Use TLS 1.2 or 1.3 only and turn off SSL and TLS 1.0/1.1.", "Use certificates from a trusted authority and renew them automatically.", "Turn on HSTS for websites.", "Test your settings regularly."], ncsc: ["tls", "cloud_tx", "pki"], nist: ["n52"] },
  "MIME": { what: "MIME describes the type of content in an email or web response, such as text, an image or an attachment. It lets different kinds of files travel together.", why: "Attackers disguise harmful files with misleading types or names. Mail and web filters that trust the declared type can be fooled.", how: ["Filter attachments by real file type, not just name.", "Block risky types such as executables and macro files.", "Set X-Content-Type-Options: nosniff on websites.", "Open untrusted attachments in a sandbox."], ncsc: ["email", "importdata", "ce_mal"], nist: ["n177"] },
  "ASCII/UTF-8": { what: "ASCII and UTF-8 are ways of turning letters and symbols into bytes. UTF-8 covers almost every language and is the web’s standard.", why: "Attackers use unusual encodings and look-alike characters to slip past filters or fake domain names. Different systems reading the same text differently can open security gaps.", how: ["Use UTF-8 consistently across systems.", "Normalise input before checking it.", "Watch for look-alike characters in domains and usernames.", "Reject invalid or over-long encodings."], ncsc: ["importdata", "dev", "caf_b4"], nist: ["n53"] },
  "EBCDIC": { what: "EBCDIC is a character encoding used mainly on IBM mainframes. Data often has to be converted when it moves between mainframes and other systems.", why: "Conversion points can corrupt data or let unexpected characters through filters. Mainframes often hold critical records, so mistakes matter.", how: ["Check data after conversion, not before.", "Use well-tested conversion tools.", "Include mainframe links in security testing and monitoring.", "Limit who can change conversion settings."], ncsc: ["importdata", "caf_b4"], nist: ["n53"] },
  "JPEG/PNG/GIF": { what: "JPEG, PNG and GIF are common image file formats. Browsers, email apps and many other programs read them automatically.", why: "Flaws in image-handling code have let specially crafted images run malicious code. Images can also hide data or tracking content.", how: ["Keep browsers, email apps and image libraries patched.", "Re-encode or sanitise images uploaded by users.", "Strip metadata such as location from published images.", "Use content disarm and reconstruction (CDR) for high-risk sources."], ncsc: ["importdata", "updates", "ce_upd"], nist: ["n40"] },
  "MPEG/MP4": { what: "MPEG and MP4 are formats for audio and video. Media players and browsers decode them automatically.", why: "Media decoders are complex and have had serious security flaws. A crafted video file can trigger code running on the device.", how: ["Keep media players, codecs and browsers patched.", "Remove media software that is not needed.", "Scan media from untrusted sources.", "Use well-maintained, sandboxed players."], ncsc: ["updates", "ce_upd", "importdata"], nist: ["n40"] },
  "XDR": { what: "External Data Representation (XDR) is a standard way to package data so different computers can read it. It is used by older systems such as NFS and ONC RPC.", why: "Services that use XDR, such as NFS and RPC, have a long history of flaws and are often too open. Decoding bad data can crash or compromise them.", how: ["Do not expose NFS or RPC services to untrusted networks.", "Use NFSv4 with Kerberos where possible.", "Keep these services patched.", "Turn off RPC services you do not use."], ncsc: ["netfund", "ce_sc", "caf_b4"], nist: ["n53"] },
  "ASN.1": { what: "ASN.1 is a standard way to describe and encode structured data. It is used inside certificates (X.509), SNMP, LDAP and many telecoms systems.", why: "ASN.1 parsers are complex, and bugs in them have caused serious flaws in crypto and network software. Malformed certificates or messages can crash or compromise systems.", how: ["Use well-maintained, widely used libraries.", "Keep crypto and network software patched.", "Reject malformed or unexpected structures.", "Fuzz-test any custom parsers."], ncsc: ["dev_test", "updates", "pki"], nist: ["n40"] },
  "JSON/XML": { what: "JSON and XML are text formats for sharing structured data between systems. Most APIs and configuration files use one of them.", why: "Unsafe parsing can let attackers read files, cause crashes or inject data (for example XML external entity attacks). Unexpected fields can change how an app behaves.", how: ["Turn off XML external entities and DTDs.", "Check data against a schema.", "Limit message size and nesting depth.", "Do not turn untrusted data straight into objects."], ncsc: ["apis", "importdata", "dev"], nist: ["n228"] },
  "Base64": { what: "Base64 turns binary data into plain text so it can travel through systems built for text. It is encoding, not encryption.", why: "Anyone can decode Base64, so it gives no protection to secrets. Attackers also use it to hide malicious scripts from simple filters.", how: ["Never use Base64 to protect secrets.", "Decode and inspect content before filtering it.", "Alert on long encoded commands in scripts.", "Encrypt sensitive data properly."], ncsc: ["caf_b3", "importdata", "soc_det"], nist: ["n53"] },
  "gzip": { what: "gzip, deflate and Brotli compress data to make it smaller and faster to send. Web servers and browsers use them all the time.", why: "Compressed archives can hide malware from scanners or expand into huge files that crash systems (zip bombs). Compressing secrets together with attacker-controlled data can also leak them in some attacks.", how: ["Limit how large data can expand when decompressed.", "Scan inside archives before allowing them.", "Do not compress secrets together with attacker-controlled data.", "Keep compression libraries patched."], ncsc: ["importdata", "ce_mal", "updates"], nist: ["n53"] },
  "TLS 1.3 policy": { what: "A TLS 1.3 policy sets which TLS versions and ciphers your systems accept. It aims for TLS 1.3, with TLS 1.2 only where needed.", why: "Old versions and weak ciphers can be downgraded or broken. A clear policy keeps encryption strong across all services.", how: ["Turn on TLS 1.3 everywhere it is supported.", "Allow TLS 1.2 only with strong ciphers.", "Turn off SSL and TLS 1.0/1.1.", "Scan services regularly to check compliance."], ncsc: ["tls", "cloud_tx", "ce_sc"], nist: ["n52"] },
  "PKI & cert lifecycle": { what: "Public key infrastructure (PKI) issues and manages digital certificates that prove identity and enable encryption. Lifecycle management covers issuing, renewing and revoking them.", why: "Expired certificates cause outages, and stolen or wrongly issued ones let attackers pose as trusted services. Many organisations do not know how many certificates they have.", how: ["Keep an inventory of every certificate and its owner.", "Automate renewal before expiry.", "Protect certificate authority and private keys, ideally in an HSM.", "Revoke certificates quickly when keys are exposed."], ncsc: ["pki", "kms", "caf_b3"], nist: ["n1800_16", "n57"] },
  "S/MIME · PGP": { what: "S/MIME and PGP encrypt and sign individual emails. Only the intended recipient can read the message, and the signature proves who sent it.", why: "Normal email can be read by mail servers and anyone who breaks into a mailbox. End-to-end encryption protects very sensitive messages wherever they are stored.", how: ["Use it for messages that need end-to-end protection.", "Manage keys and certificates centrally.", "Plan how to recover keys if someone leaves.", "Combine it with transport encryption (TLS)."], ncsc: ["email", "email_tx", "caf_b3"], nist: ["n177"] },
  "Post-quantum crypto": { what: "Post-quantum cryptography (PQC) is new encryption designed to resist future quantum computers. Standards such as ML-KEM are now published.", why: "A large quantum computer could break today’s public-key encryption. Data captured now could be decrypted later, so long-lived secrets are at risk.", how: ["List where you use public-key cryptography.", "Ask suppliers for their PQC plans.", "Prioritise systems that protect long-lived data.", "Follow NCSC migration timelines."], ncsc: ["pqc", "pqc_time"], nist: ["fips203", "ir8547"] },
  "CDR": { what: "Content disarm and reconstruction (CDR) rebuilds files such as documents and images, keeping only known-safe content. Macros and hidden code are removed.", why: "Antivirus only catches threats it recognises. CDR removes active content whether it is known or not, which helps against new attacks.", how: ["Apply it to files from email, the web and uploads.", "Keep the original file for authorised access if needed.", "Tell users when content has been removed.", "Combine it with sandboxing for high-risk sources."], ncsc: ["importdata", "xdomain", "malware"], nist: ["n53"] },
  "Input canonicalisation": { what: "Canonicalisation turns input into one standard form before it is checked. For example, it decodes URLs and resolves file paths.", why: "Attackers encode the same harmful input in many ways to get past filters. Checking before normalising lets disguised attacks through.", how: ["Decode and normalise input once, then validate it.", "Use allow-lists of expected values.", "Resolve file paths before checking access.", "Use well-tested framework functions."], ncsc: ["dev", "importdata", "caf_b4"], nist: ["n218"] },
  "Safe deserialisation": { what: "Deserialisation turns stored or received data back into objects inside an app. Safe deserialisation only accepts expected types and structures.", why: "Unsafe deserialisation of untrusted data can let attackers run code on the server. It has caused many serious breaches.", how: ["Do not deserialise untrusted data into native objects.", "Use simple data formats such as JSON with a schema.", "Restrict which types may be created.", "Keep libraries patched and test with fuzzing."], ncsc: ["dev", "dev_test", "importdata"], nist: ["n218"] },

  /* ---------- L5 Session ---------- */
  "NetBIOS": { what: "NetBIOS is an old Windows protocol for naming and sharing on local networks. It is mostly replaced by DNS and modern SMB.", why: "NetBIOS and related name services (LLMNR) can be tricked into giving out password hashes. They also reveal information about a network.", how: ["Turn off NetBIOS over TCP/IP and LLMNR where not needed.", "Block NetBIOS ports at network boundaries.", "Use DNS for name resolution.", "Monitor for name-poisoning tools."], ncsc: ["lateral", "ce_sc", "netfund"], nist: ["n53"] },
  "RPC": { what: "Remote Procedure Call (RPC) lets one computer ask another to run a task. Windows and many enterprise systems use it heavily.", why: "RPC services are often used to move between systems after a break-in. Some have had serious remote flaws.", how: ["Block RPC between networks that do not need it.", "Use RPC signing and encryption where available.", "Keep systems patched.", "Watch for unusual RPC use between workstations."], ncsc: ["lateral", "ce_fw", "caf_b4"], nist: ["n53"] },
  "SOCKS": { what: "SOCKS is a proxy protocol that relays network connections for other programs. It can carry almost any kind of traffic.", why: "Attackers use SOCKS proxies to tunnel through networks and hide their traffic. An open proxy can be abused by anyone.", how: ["Require login on any SOCKS proxy.", "Do not allow open proxies to the internet.", "Block unapproved proxy traffic.", "Look for unexpected proxy tools on devices."], ncsc: ["netfund", "browser", "caf_c1"], nist: ["n53"] },
  "PPTP": { what: "PPTP is an old VPN protocol from the 1990s. Its security is known to be broken.", why: "PPTP encryption can be cracked, exposing passwords and traffic. It should not be used for any remote access.", how: ["Replace PPTP with IPsec or modern TLS-based VPNs.", "Block PPTP at the firewall (TCP 1723 and GRE).", "Check devices and routers for PPTP left turned on.", "Use MFA on all remote access."], ncsc: ["vpn", "ipsec"], nist: ["n77"] },
  "L2TP": { what: "L2TP is a tunnelling protocol often used with IPsec to build VPNs. On its own it does not encrypt anything.", why: "L2TP without IPsec sends traffic in the clear. Weak pre-shared keys also make some set-ups easy to break.", how: ["Always use L2TP with IPsec, or a modern VPN instead.", "Use certificates rather than shared keys.", "Require MFA for users.", "Keep VPN gateways patched."], ncsc: ["vpn", "ipsec"], nist: ["n77"] },
  "H.245": { what: "H.245 is the control protocol for H.323 video and voice calls. It negotiates how media is sent once a call is set up.", why: "Older video-conferencing systems are often left exposed and unpatched. Attackers have used them to listen in or take control of rooms.", how: ["Do not expose conferencing systems directly to the internet.", "Use encrypted calls where supported.", "Keep video-conferencing equipment patched.", "Turn off auto-answer."], ncsc: ["netfund", "updates", "caf_b4"], nist: ["n58"] },
  "SDP": { what: "Session Description Protocol (SDP) describes the media in a call, such as codecs and addresses. It travels inside SIP and WebRTC messages.", why: "SDP can reveal internal network addresses and be changed to redirect media. Tampered SDP can take calls somewhere else.", how: ["Protect signalling with TLS.", "Use a session border controller to check and rewrite SDP.", "Use SRTP so media is encrypted.", "Limit which media ports are open."], ncsc: ["tls", "netfund"], nist: ["n58"] },
  "RTCP": { what: "RTCP reports on the quality of voice and video streams, such as packet loss. It travels alongside the media stream.", why: "Unprotected control messages can be faked to disrupt calls or reveal call details. It is part of the voice system attack surface.", how: ["Use SRTP/SRTCP to protect media and control messages.", "Allow media ports only through a session border controller.", "Watch call quality data for unusual patterns.", "Keep voice systems patched."], ncsc: ["netfund", "tls"], nist: ["n58"] },
  "Secure session tokens": { what: "Session tokens, such as cookies, keep you logged in after you sign in. Secure tokens are random, protected and expire.", why: "If an attacker steals a session token, they can act as the user without the password or MFA. Token theft is now common in phishing kits.", how: ["Use long, random tokens from your framework.", "Set cookies as Secure, HttpOnly and SameSite.", "Keep token lifetimes short and end sessions at logout.", "Revoke sessions when risk changes."], ncsc: ["cloud_id", "authpol", "caf_b2"], nist: ["n63b"] },
  "Timeouts & re-auth": { what: "Timeouts end idle sessions, and re-authentication asks users to prove who they are again for sensitive actions. Both limit how long a session can be misused.", why: "Long-lived sessions on shared or lost devices give attackers easy access. Re-checking identity protects the riskiest actions.", how: ["Set idle and total session timeouts by risk.", "Ask for MFA again before sensitive actions.", "Lock screens automatically on devices.", "Shorten sessions for admin access."], ncsc: ["authpol", "caf_b2", "ce_sc"], nist: ["n63b"] },
  "Mutual TLS": { what: "Mutual TLS (mTLS) means both sides of a connection prove their identity with certificates. It is common between services and devices.", why: "Normal TLS only proves the server is genuine. mTLS stops unknown clients from connecting even if they reach the service.", how: ["Issue certificates to services and devices from a managed CA.", "Rotate certificates automatically and keep lifetimes short.", "Check certificate revocation.", "Use a service mesh to apply mTLS at scale."], ncsc: ["tls", "zt_auth", "zt_id"], nist: ["n207", "n204"] },
  "Anti-replay": { what: "Anti-replay protections stop an attacker from capturing a valid message and sending it again. They use one-time numbers (nonces), timestamps or sequence numbers.", why: "A replayed login or payment message can repeat an action without the attacker knowing any secrets. Many protocols are vulnerable unless replay is blocked.", how: ["Use protocols with built-in replay protection such as TLS and IPsec.", "Add unique IDs and timestamps to sensitive requests.", "Reject duplicate or stale messages.", "Keep clocks in sync (NTP)."], ncsc: ["tls", "ipsec", "apis"], nist: ["n53"] },
  "SMB/RPC signing": { what: "SMB and RPC signing adds a check to each message so it cannot be changed or relayed. It is a setting in Windows networks.", why: "Without signing, attackers can relay captured logins to other servers (NTLM relay). This is a common way to spread through Windows networks.", how: ["Require SMB signing on all clients and servers.", "Turn on LDAP signing and channel binding.", "Reduce or turn off NTLM where possible.", "Test changes on older systems first."], ncsc: ["lateral", "ce_sc", "caf_b4"], nist: ["n53"] },
  "ZTNA broker": { what: "A zero trust network access (ZTNA) broker connects users to specific apps rather than to a whole network. Each request is checked for identity and device health.", why: "Traditional VPNs often give users wide network access once connected. ZTNA limits what an attacker can reach with a stolen login.", how: ["Publish apps through the broker instead of a full VPN.", "Check user, device and context for every connection.", "Start with your highest-risk apps.", "Log and review access decisions."], ncsc: ["ztna", "zt_p", "zt_pol"], nist: ["n207"] },
  "DPoP / token binding": { what: "DPoP and token binding tie an access token to a key held by the user’s device. A stolen token is useless without that key.", why: "Bearer tokens work for whoever holds them, so theft gives full access. Binding tokens to a device blocks this kind of replay.", how: ["Use DPoP or mTLS-bound tokens for high-value APIs.", "Keep device keys in secure hardware where possible.", "Keep token lifetimes short.", "Check that your identity provider supports binding."], ncsc: ["apis", "zt_auth", "cloud_id"], nist: ["n63b"] },
  "Session recording": { what: "Session recording captures what happens during privileged or remote sessions, such as admin logins. Recordings can be replayed and searched.", why: "Admins and suppliers have powerful access, and misuse can be hard to prove. Recording discourages misuse and helps investigations.", how: ["Record privileged and supplier sessions through a PAM or gateway.", "Tell users that sessions are recorded.", "Protect recordings from changes and limit who can view them.", "Review samples and high-risk sessions."], ncsc: ["ssa_log", "ssa_pam", "caf_c1"], nist: ["n53"] },

  /* ---------- L4 Transport ---------- */
  "TCP": { what: "TCP is the protocol that delivers data reliably and in order between two computers. Web, email and most business traffic use it.", why: "Open TCP ports show attackers which services are running. TCP can also be targeted by floods and connection hijacks.", how: ["Only open the ports you really need.", "Use firewalls to limit who can connect.", "Turn on SYN flood protection.", "Scan your own internet-facing ports regularly."], ncsc: ["ce_fw", "netfund", "caf_b4"], nist: ["n41"] },
  "UDP": { what: "UDP sends data quickly without setting up a connection or checking delivery. DNS, voice, video and gaming use it.", why: "Because UDP does not check who sent a packet, it is easy to spoof. Attackers use this for large reflection and amplification DDoS attacks.", how: ["Block UDP services you do not need.", "Rate-limit services such as DNS and NTP.", "Stop spoofed traffic leaving your network.", "Use DDoS protection for public services."], ncsc: ["dos", "ce_fw", "netfund"], nist: ["n41"] },
  "QUIC": { what: "QUIC is a newer transport protocol that runs over UDP and includes encryption. It powers HTTP/3 and is used by most major websites.", why: "Because QUIC is always encrypted, older security tools may not be able to inspect it. Some may let it pass without checks.", how: ["Decide whether your web filters can inspect QUIC.", "If not, block UDP 443 so browsers fall back to TCP.", "Keep QUIC-capable servers patched.", "Include QUIC in DDoS planning."], ncsc: ["browser", "tls", "netfund"], nist: ["n52"] },
  "SCTP": { what: "SCTP is a transport protocol used mainly in telecoms networks for signalling. It can use several network paths at once.", why: "SCTP is often overlooked by firewalls and monitoring. Telecoms signalling networks have been abused to track or intercept users.", how: ["Block SCTP where it is not needed.", "Use firewalls that understand SCTP in telecoms networks.", "Monitor signalling traffic for abuse.", "Keep telecoms equipment patched."], ncsc: ["netfund", "caf_b5"], nist: ["n187"] },
  "DCCP": { what: "DCCP is a rarely used transport protocol for streaming data with congestion control. Most networks do not need it.", why: "Unused protocols increase the attack surface, and DCCP code in operating systems has had serious bugs. Few security tools look at it.", how: ["Turn off DCCP in operating systems where it is not needed.", "Block it at network boundaries.", "Keep operating systems patched.", "Review which protocols are allowed."], ncsc: ["ce_sc", "updates"], nist: ["n53"] },
  "MPTCP": { what: "Multipath TCP (MPTCP) lets one connection use several network paths at once, such as Wi-Fi and mobile data. Some phones and servers use it.", why: "Traffic split across paths can avoid inspection by tools that only see one part. It can also bypass network controls.", how: ["Check whether your security tools handle MPTCP.", "Turn it off where it is not needed.", "Apply the same controls on every network path.", "Monitor for unexpected use."], ncsc: ["netfund", "zt_net"], nist: ["n53"] },
  "SPX": { what: "SPX is the transport protocol from old Novell IPX networks. It is almost never used today.", why: "Legacy protocols left running are unpatched and poorly monitored. They can give attackers hidden paths through a network.", how: ["Find and remove any legacy IPX/SPX use.", "Block it at network boundaries.", "Replace old systems that still need it.", "Record exceptions in your risk register."], ncsc: ["obsolete", "ce_sc"], nist: ["n53"] },
  "Stateful firewall": { what: "A stateful firewall allows or blocks traffic and remembers each connection. Replies to allowed traffic are let back in automatically.", why: "Without a firewall, every service is reachable by anyone who can route to it. Firewalls are a basic requirement of Cyber Essentials.", how: ["Block everything by default and allow only what is needed.", "Document why each rule exists and remove old rules.", "Change default admin passwords and limit admin access.", "Use host firewalls on devices too."], ncsc: ["ce_fw", "netfund", "caf_b4"], nist: ["n41"] },
  "SYN cookies": { what: "SYN cookies are a technique that lets a server handle a flood of fake connection requests without running out of memory. They are built into most operating systems.", why: "SYN floods try to fill a server’s connection table so real users cannot connect. SYN cookies keep services available during these attacks.", how: ["Turn on SYN cookies on servers and load balancers.", "Use upstream DDoS protection for large floods.", "Monitor connection rates.", "Test under load."], ncsc: ["dos", "dos_up"], nist: ["n53"] },
  "DDoS & rate limiting": { what: "DDoS protection absorbs and filters floods of traffic aimed at taking a service offline. Rate limiting caps how many requests one source can make.", why: "DDoS attacks can take public services offline for hours. Rate limits also slow down password guessing and scraping.", how: ["Use a DDoS protection service for public services.", "Set rate limits on logins and APIs.", "Have a DDoS response plan and know who to call.", "Test your service’s ability to scale."], ncsc: ["dos", "dos_up", "dos_plan"], nist: ["n53"] },
  "IDS / IPS": { what: "Intrusion detection and prevention systems (IDS/IPS) look at network traffic for signs of attacks. An IPS can also block them.", why: "Some attacks look like normal traffic to a firewall. IDS/IPS spots known attack patterns and gives warnings.", how: ["Place sensors at key points such as the internet edge.", "Keep signatures up to date.", "Tune alerts so the team can act on them.", "Send alerts to your SIEM."], ncsc: ["caf_c1", "soc_det", "s_log"], nist: ["n94"] },
  "TCP-AO": { what: "TCP Authentication Option (TCP-AO) adds a cryptographic check to each TCP packet. It is mainly used to protect routing sessions such as BGP.", why: "Without it, attackers can inject fake packets to reset or hijack long-lived connections between routers. It replaces the older, weaker MD5 option.", how: ["Use TCP-AO for BGP and other router sessions where supported.", "Use strong, unique keys and rotate them.", "Move away from TCP MD5.", "Monitor for session resets."], ncsc: ["netfund", "caf_b5"], nist: ["n189"] },
  "Load balancer / proxy": { what: "A load balancer or reverse proxy spreads traffic across servers and hides them from the internet. It often handles TLS too.", why: "It is the front door for many services, so its settings matter. Done well, it reduces exposure and absorbs attacks.", how: ["Keep backend servers off the internet.", "Use strong TLS settings at the proxy.", "Add security headers and request limits.", "Keep the load balancer patched and admin access restricted."], ncsc: ["cloud_if", "tls", "dos_scale"], nist: ["n44"] },
  "Micro-segmentation": { what: "Micro-segmentation splits a network into small zones, down to single apps or servers. Only allowed traffic can pass between them.", why: "In a flat network, one infected computer can reach everything. Segmentation stops attackers and ransomware from spreading.", how: ["Map how your applications talk to each other.", "Allow only needed connections between zones.", "Start with your most critical systems.", "Monitor blocked traffic for signs of attack."], ncsc: ["lateral", "d_impact", "zt_net"], nist: ["n207"] },

  /* ---------- L3 Network ---------- */
  "IPv4": { what: "IPv4 is the main addressing system of the internet, giving each device a numbered address. It routes packets between networks.", why: "IPv4 does not check that a packet’s source address is real, which makes spoofing easy. Poorly planned address ranges also make networks hard to secure.", how: ["Filter spoofed addresses at your network edge.", "Plan address ranges to match security zones.", "Use private addressing internally.", "Keep an up-to-date IP address inventory."], ncsc: ["netfund", "s_asset"], nist: ["n53"] },
  "IPv6": { what: "IPv6 is the newer internet addressing system with a far larger address space. Many devices have it turned on by default.", why: "IPv6 is often left on without being managed or monitored, creating hidden paths around IPv4 controls. Rogue router messages can redirect traffic.", how: ["Apply the same firewall and monitoring rules to IPv6 as IPv4.", "Turn on RA Guard on switches.", "Turn IPv6 off only if you are sure you do not need it.", "Include IPv6 in testing."], ncsc: ["netfund", "ce_fw"], nist: ["n119"] },
  "ICMP/ICMPv6": { what: "ICMP carries network error and test messages, such as ping and ‘destination unreachable’. IPv6 depends on ICMPv6 to work properly.", why: "Attackers use ICMP to map networks, flood services and sometimes smuggle data. Blocking it completely can break networks, especially IPv6.", how: ["Allow only the ICMP types you need.", "Rate-limit ICMP at the edge.", "Never block ICMPv6 types needed for IPv6 to work.", "Watch for unusual ICMP volume."], ncsc: ["netfund", "ce_fw"], nist: ["n41"] },
  "IGMP": { what: "IGMP lets devices join multicast groups so one stream can reach many receivers. It is used for IPTV and some trading or industrial systems.", why: "Misused IGMP can flood networks or let unauthorised devices receive streams. It is rarely monitored.", how: ["Use IGMP snooping on switches.", "Limit which groups devices can join.", "Block multicast at boundaries where not needed.", "Monitor multicast traffic levels."], ncsc: ["netfund"], nist: ["n53"] },
  "OSPF": { what: "OSPF is a routing protocol that lets routers inside an organisation share routes automatically. It quickly adapts when links fail.", why: "If attackers can send fake OSPF updates, they can redirect or black-hole traffic. Unauthenticated routing is an easy target inside a network.", how: ["Turn on OSPF authentication with strong keys.", "Make interfaces passive where no router neighbours are expected.", "Limit who can manage routers.", "Monitor routing changes."], ncsc: ["netfund", "caf_b5"], nist: ["n53"] },
  "BGP": { what: "BGP is the routing protocol that connects networks across the internet. It decides which path traffic takes between organisations.", why: "BGP trusts what neighbours announce, so mistakes or attacks can hijack traffic for whole address ranges. Hijacks have redirected banking and cloud traffic.", how: ["Use RPKI to sign your routes and check others’.", "Filter routes you accept from peers.", "Protect BGP sessions with TCP-AO or MD5.", "Monitor for hijacks of your address space."], ncsc: ["netfund", "caf_b5"], nist: ["n189", "n54"] },
  "RIP": { what: "RIP is an old, simple routing protocol. Most networks have replaced it.", why: "RIPv1 has no authentication, so anyone on the network can inject routes. Legacy routing is easy to abuse.", how: ["Replace RIP with OSPF or static routes.", "If you must use it, use RIPv2 with authentication.", "Make interfaces passive where no routers are expected.", "Monitor routing changes."], ncsc: ["obsolete", "netfund"], nist: ["n53"] },
  "EIGRP": { what: "EIGRP is a routing protocol originally from Cisco, used inside organisations. Routers share routes with neighbours automatically.", why: "Without authentication, fake neighbours can inject routes and redirect traffic. Routing control is valuable to attackers.", how: ["Turn on EIGRP authentication.", "Use passive interfaces where no neighbours are expected.", "Limit admin access to routers.", "Log neighbour and route changes."], ncsc: ["netfund", "caf_b5"], nist: ["n53"] },
  "IS-IS": { what: "IS-IS is a routing protocol used mainly in large service-provider and data-centre networks. It works like OSPF.", why: "Unauthenticated IS-IS can be tampered with to redirect or disrupt traffic. Core network routing affects every service on top.", how: ["Turn on IS-IS authentication.", "Limit physical and admin access to core routers.", "Monitor routing changes.", "Keep router software patched."], ncsc: ["netfund", "caf_b5"], nist: ["n53"] },
  "GRE": { what: "GRE wraps one network packet inside another to create a tunnel between sites. It does not encrypt anything on its own.", why: "Traffic in GRE tunnels can be read or changed if not protected. Attackers also use tunnels to bypass network controls.", how: ["Protect GRE tunnels with IPsec.", "Allow GRE only between known endpoints.", "Inspect traffic after it leaves the tunnel.", "Remove unused tunnels."], ncsc: ["ipsec", "netfund"], nist: ["n77"] },
  "IPX": { what: "IPX is the network protocol from old Novell NetWare systems. It is now almost entirely obsolete.", why: "Legacy protocols are not patched or monitored. Any remaining use is a hidden risk.", how: ["Find and retire any remaining IPX use.", "Block it on routers and firewalls.", "Isolate old systems that still need it.", "Record the risk if it must stay."], ncsc: ["obsolete", "s_asset"], nist: ["n53"] },
  "Packet filter / ACLs": { what: "Packet filters and access control lists (ACLs) allow or block traffic based on addresses and ports. They run on routers, switches and cloud networks.", why: "They are the simplest way to stop unwanted traffic reaching systems. Rules that are too open, or forgotten, leave services exposed.", how: ["Block by default and allow only what is needed.", "Review rules regularly and remove unused ones.", "Document an owner and reason for each rule.", "Use cloud security groups the same way."], ncsc: ["ce_fw", "netfund", "caf_b4"], nist: ["n41"] },
  "IPsec VPN": { what: "An IPsec VPN encrypts traffic between sites or between a device and the network. It protects data crossing untrusted networks.", why: "Data crossing the internet can be intercepted. VPN gateways are also a top target, so their security is critical.", how: ["Use strong, modern IPsec settings (IKEv2).", "Use certificates rather than shared keys.", "Patch VPN gateways quickly, as flaws are exploited fast.", "Require MFA for remote users."], ncsc: ["ipsec", "vpn", "heightened"], nist: ["n77"] },
  "Anti-spoofing (uRPF)": { what: "Anti-spoofing checks drop packets with fake source addresses. Unicast reverse path forwarding (uRPF) does this automatically on routers.", why: "Spoofed packets power many DDoS attacks and can bypass address-based rules. Filtering them protects you and others.", how: ["Turn on uRPF or ingress filtering at network edges.", "Drop packets from outside that claim to come from your own ranges.", "Stop spoofed traffic leaving your network.", "Ask your ISP to filter too."], ncsc: ["netfund", "dos_up"], nist: ["n189"] },
  "RPKI / ROV": { what: "RPKI lets network owners sign which networks may announce their IP addresses. Route origin validation (ROV) uses this to reject false routes.", why: "Without RPKI, anyone can announce your addresses by mistake or on purpose. ROV blocks many route hijacks automatically.", how: ["Create route origin authorisations (ROAs) for your address space.", "Turn on ROV on your routers, or ask your ISP to.", "Keep ROAs up to date when routing changes.", "Monitor for invalid announcements."], ncsc: ["netfund", "caf_b5"], nist: ["n189"] },
  "Routing auth": { what: "Routing authentication makes routers prove their identity before accepting route updates. It applies to OSPF, BGP, IS-IS and others.", why: "Without it, a rogue device can inject routes and redirect traffic. It is a simple step that blocks a whole class of attacks.", how: ["Turn on authentication for every routing protocol.", "Use strong keys and rotate them.", "Use TCP-AO for BGP where supported.", "Alert on new routing neighbours."], ncsc: ["netfund", "caf_b5"], nist: ["n189"] },
  "Segmentation (VRF / zones)": { what: "Segmentation splits a network into separate zones, for example with VRFs or firewalls. Each zone holds systems with similar trust and purpose.", why: "Separating zones limits how far an attacker can spread. It also protects critical systems such as operational technology from office IT.", how: ["Group systems into zones by risk and function.", "Control and log traffic between zones.", "Keep management and OT networks separate.", "Test that zones really are separated."], ncsc: ["lateral", "d_impact", "ot"], nist: ["n215"] },
  "DDoS scrubbing / RTBH": { what: "DDoS scrubbing sends attack traffic through a provider that filters it out. Remotely triggered black hole (RTBH) routing drops traffic to an address under attack.", why: "Large DDoS attacks can overwhelm your internet links before anything on-site can help. Upstream filtering keeps the rest of your network online.", how: ["Arrange DDoS scrubbing with your ISP or a provider.", "Agree in advance how to switch it on.", "Use RTBH as a last resort to protect other services.", "Test the process."], ncsc: ["dos_up", "dos_plan", "dos"], nist: ["n189"] },
  "ICMP filtering": { what: "ICMP filtering allows only the ICMP messages a network needs and blocks the rest. It reduces mapping and flood attacks.", why: "Open ICMP helps attackers map networks and can be used in floods. Blocking too much breaks networks, so balance is needed.", how: ["Allow essential ICMP such as ‘packet too big’.", "Rate-limit echo requests at the edge.", "Keep the ICMPv6 types IPv6 needs.", "Review filters after network changes."], ncsc: ["netfund", "ce_fw"], nist: ["n41"] },

  /* ---------- L2 Data Link ---------- */
  "Ethernet 802.3": { what: "Ethernet is the standard for wired local networks. It moves frames between devices using MAC addresses.", why: "Anyone who can plug into a network port may be able to join the network. Ethernet itself has no access control.", how: ["Use 802.1X so only known devices can connect.", "Turn off unused switch ports.", "Put meeting-room and public ports on a separate network.", "Physically secure network cabinets."], ncsc: ["netfund", "caf_b5"], nist: ["n53"] },
  "Wi-Fi 802.11 MAC": { what: "The 802.11 MAC layer controls how Wi-Fi devices join networks and share the radio. It manages connections, encryption keys and roaming.", why: "Wi-Fi reaches beyond your walls, so attackers can try to connect or set up fake access points nearby. Weak security exposes traffic and passwords.", how: ["Use WPA3-Enterprise or at least WPA2-Enterprise.", "Turn on protected management frames.", "Keep guest Wi-Fi separate from internal networks.", "Monitor for rogue access points."], ncsc: ["netfund", "zt_net"], nist: ["n153", "n97"] },
  "ARP": { what: "ARP links IP addresses to hardware MAC addresses on a local network. Devices use it to find each other.", why: "ARP trusts any reply, so attackers can pretend to be the gateway and intercept traffic (ARP poisoning). It is a common man-in-the-middle technique.", how: ["Turn on Dynamic ARP Inspection on switches.", "Use DHCP snooping to build trusted address tables.", "Encrypt traffic so interception reveals little.", "Monitor for ARP anomalies."], ncsc: ["netfund", "tls"], nist: ["n53"] },
  "PPP": { what: "Point-to-Point Protocol (PPP) carries network traffic over a direct link, such as some broadband or serial connections. It handles login and link set-up.", why: "Older PPP login methods (PAP) send passwords in clear text. Weak link security can expose traffic.", how: ["Use stronger authentication instead of PAP.", "Encrypt traffic that crosses the link.", "Change default credentials on modems and routers.", "Keep edge devices patched."], ncsc: ["ce_sc", "netfund"], nist: ["n53"] },
  "802.1Q VLAN": { what: "802.1Q tags network frames so one physical network can carry several separate virtual LANs (VLANs). VLANs group devices logically.", why: "Misconfigured VLANs can let attackers hop between them. VLANs on their own are separation, not strong security.", how: ["Do not use VLAN 1 or the native VLAN for user traffic.", "Turn off automatic trunking on user ports.", "Filter traffic between VLANs with a firewall.", "Review VLAN settings regularly."], ncsc: ["lateral", "netfund"], nist: ["n53"] },
  "STP/RSTP": { what: "Spanning Tree Protocol (STP/RSTP) prevents loops in switched networks. It chooses which links are active.", why: "An attacker or careless device can send fake STP messages to take over the network’s layout or cause outages. Loops can bring a network down.", how: ["Turn on BPDU guard on user ports.", "Use root guard to protect the chosen root switch.", "Set the root switch deliberately.", "Monitor topology changes."], ncsc: ["netfund", "caf_b5"], nist: ["n53"] },
  "LLDP/CDP": { what: "LLDP and CDP let network devices announce what they are to their neighbours. Admins use them to map networks.", why: "These announcements tell anyone plugged in the device model, software version and addresses. That helps attackers plan.", how: ["Turn off LLDP/CDP on user-facing ports.", "Keep it only where needed, such as for IP phones.", "Patch devices with known LLDP/CDP flaws.", "Limit what information is shared."], ncsc: ["ce_sc", "netfund"], nist: ["n53"] },
  "LACP": { what: "LACP joins several physical links into one faster, more resilient link. It is common between switches and servers.", why: "Misconfiguration can cause outages or let a rogue device join a link group. It mainly affects availability.", how: ["Only enable LACP on ports that need it.", "Use active mode on known devices.", "Monitor link changes.", "Document link groups."], ncsc: ["caf_b5", "netfund"], nist: ["n53"] },
  "MPLS": { what: "MPLS is a service-provider technology that carries traffic along set paths between sites. Many organisations use MPLS links from telecoms providers.", why: "MPLS separates customers but does not encrypt traffic. Data is only as safe as the provider’s network and staff.", how: ["Encrypt sensitive traffic over MPLS with IPsec.", "Include the provider in supply chain checks.", "Monitor for unexpected routes.", "Plan for provider outages."], ncsc: ["ipsec", "supply_p", "zt_net"], nist: ["n77"] },
  "HDLC": { what: "HDLC is an older protocol for sending data over serial and leased-line links. It is still found in some legacy and industrial networks.", why: "Legacy serial links are often unencrypted and forgotten. They can carry sensitive control traffic.", how: ["Find any remaining HDLC links and record them.", "Encrypt traffic or replace the links where possible.", "Physically protect serial equipment.", "Include it in OT security plans."], ncsc: ["ot", "obsolete"], nist: ["n82"] },
  "Frame Relay": { what: "Frame Relay is an older wide-area network service for linking sites. Most providers have retired it.", why: "Old WAN services are unsupported and unencrypted. Remaining links are a hidden risk.", how: ["Plan to migrate off Frame Relay.", "Encrypt traffic until it is replaced.", "Record the risk while it remains.", "Check provider support dates."], ncsc: ["obsolete", "ipsec"], nist: ["n53"] },
  "802.1X / NAC": { what: "802.1X makes devices prove who they are before getting network access. Network access control (NAC) can also check device health.", why: "Without it, anyone who plugs in or joins Wi-Fi may get access. 802.1X stops unknown devices at the door.", how: ["Use certificates for device authentication.", "Put unknown devices in a restricted network.", "Check device health such as patches and EDR.", "Plan for printers and devices that cannot use 802.1X."], ncsc: ["zt_id", "netfund", "caf_b2"], nist: ["n53"] },
  "MACsec 802.1AE": { what: "MACsec encrypts traffic on each wired link between switches or devices. It protects against tapping cables inside buildings and data centres.", why: "Traffic on internal links is often unencrypted, and someone with physical access can tap it. MACsec protects data on every hop.", how: ["Turn on MACsec for links between sites or through untrusted spaces.", "Use strong keys with automatic key management.", "Check hardware support before buying.", "Monitor for MACsec session failures."], ncsc: ["netfund", "cloud_tx"], nist: ["n53"] },
  "Port security": { what: "Port security limits which devices, by MAC address, can use a switch port. It can shut the port if an unknown device connects.", why: "It stops casual plugging-in of unauthorised devices and MAC flooding attacks. It is simple but can be fooled by copied addresses.", how: ["Limit the number of devices per port.", "Shut or restrict ports on violation.", "Turn off unused ports.", "Use 802.1X for stronger control."], ncsc: ["netfund", "periph"], nist: ["n53"] },
  "Dynamic ARP Inspection": { what: "Dynamic ARP Inspection (DAI) checks ARP messages on a switch against trusted records. It drops fake ones.", why: "It stops ARP poisoning, which attackers use to intercept traffic on local networks. It is one of the dataflow defences on this poster.", how: ["Turn on DHCP snooping first, because DAI uses its records.", "Turn on DAI on user VLANs.", "Add static entries for devices with fixed addresses.", "Monitor dropped ARP messages."], ncsc: ["netfund", "lateral"], nist: ["n53"] },
  "DHCP snooping": { what: "DHCP snooping lets switches allow DHCP replies only from trusted ports. It also records which address each device was given.", why: "A rogue DHCP server can send devices to an attacker’s gateway or DNS. Snooping blocks this.", how: ["Mark only ports to real DHCP servers as trusted.", "Turn it on for all user VLANs.", "Use its records for ARP inspection.", "Alert on blocked DHCP replies."], ncsc: ["netfund"], nist: ["n53"] },
  "Private VLANs": { what: "Private VLANs stop devices on the same VLAN from talking to each other directly. They can only reach the gateway or shared services.", why: "Devices such as guest laptops or hosted servers rarely need to talk to each other. Isolating them stops attacks spreading sideways.", how: ["Use them for guest, hotel or shared hosting networks.", "Allow only gateway and needed shared services.", "Test isolation after changes.", "Combine with firewall rules."], ncsc: ["lateral", "d_impact"], nist: ["n53"] },
  "BPDU / root guard": { what: "BPDU guard and root guard protect the spanning tree layout of a switched network. They block unexpected switch messages on user ports.", why: "Without them, a rogue device can take over spanning tree and redirect traffic or cause outages. They are low-effort protections.", how: ["Turn on BPDU guard on all user ports.", "Turn on root guard on ports that should never lead to the root switch.", "Alert when a port is shut down by guard.", "Document your intended root switch."], ncsc: ["netfund", "caf_b5"], nist: ["n53"] },
  "RA Guard": { what: "RA Guard blocks fake IPv6 router advertisements on switch ports. Only real routers can tell devices how to reach the network.", why: "A rogue router advertisement can make devices send traffic through an attacker. This works even on networks that think they only use IPv4.", how: ["Turn on RA Guard on user-facing ports.", "Allow advertisements only from router ports.", "Include IPv6 in network monitoring.", "Test on networks with IPv6 turned on by default."], ncsc: ["netfund"], nist: ["n119"] },
  "WPA3-Enterprise": { what: "WPA3-Enterprise is the strongest current Wi-Fi security for organisations. Each user or device logs in individually, usually with certificates.", why: "Shared Wi-Fi passwords leak and cannot be withdrawn from one person. Enterprise mode gives individual access and stronger encryption.", how: ["Use WPA3-Enterprise, or WPA2-Enterprise where devices cannot support it.", "Use certificate-based login (EAP-TLS).", "Turn on protected management frames.", "Keep guest Wi-Fi separate."], ncsc: ["zt_id", "netfund"], nist: ["n153", "n97"] },
  "WIPS": { what: "A wireless intrusion prevention system (WIPS) watches the airwaves for rogue access points and Wi-Fi attacks. It can alert on them or contain them.", why: "Attackers can set up fake ‘evil twin’ networks or connect rogue access points. WIPS spots these threats.", how: ["Use your Wi-Fi system’s built-in WIPS features.", "Alert on rogue and look-alike networks.", "Check legal limits before automatic containment.", "Investigate unknown access points quickly."], ncsc: ["caf_c1", "netfund"], nist: ["n153"] },

  /* ---------- L1 Physical ---------- */
  "Ethernet PHY (BASE-T)": { what: "BASE-T is copper network cabling and the electrical signals that run over it. It connects most desks, phones and access points.", why: "Copper cables can be tapped or plugged into by anyone with physical access. Exposed ports in public areas are a risk.", how: ["Secure network cabinets and patch panels.", "Turn off or isolate unused wall ports.", "Run cables through controlled spaces.", "Use 802.1X so a plug-in alone does not give access."], ncsc: ["netfund", "caf_b5"], nist: ["n53"] },
  "Fibre (BASE-SX/LX)": { what: "Fibre carries network data as light through glass cables. It links buildings, floors and data centres.", why: "Fibre is harder to tap than copper but it can be done with clip-on devices. Cut fibres can take whole sites offline.", how: ["Route fibre through secure, monitored paths.", "Encrypt sensitive traffic (MACsec or IPsec).", "Use diverse routes for resilience.", "Monitor for signal loss that may show tampering."], ncsc: ["caf_b5", "d_disrupt"], nist: ["n53"] },
  "802.11 PHY": { what: "The 802.11 physical layer is the radio part of Wi-Fi. It sends and receives signals in the 2.4, 5 and 6 GHz bands.", why: "Radio signals pass through walls, so anyone nearby can listen or jam them. Signal leaking outside buildings widens the attack area.", how: ["Plan access point placement and power to limit leakage.", "Use strong Wi-Fi encryption.", "Monitor for interference and jamming.", "Have a wired fallback for critical systems."], ncsc: ["netfund", "zt_net"], nist: ["n153"] },
  "Bluetooth PHY": { what: "Bluetooth is short-range radio for linking headsets, keyboards and other accessories. It is turned on in most phones and laptops.", why: "Bluetooth flaws have allowed attackers nearby to take over devices without any clicks. Pairing can also be abused.", how: ["Keep devices patched.", "Turn Bluetooth off when not needed on high-risk devices.", "Make devices non-discoverable.", "Use only approved accessories."], ncsc: ["periph", "updates"], nist: ["n121"] },
  "5G NR": { what: "5G New Radio is the latest mobile network radio technology. It connects phones, routers and IoT devices to mobile networks.", why: "Mobile links carry business traffic outside your control. Fake base stations and weak device settings can expose traffic.", how: ["Encrypt business traffic end to end rather than relying on the mobile network.", "Manage mobile devices with MDM.", "Keep devices and modems patched.", "Use providers with strong security commitments."], ncsc: ["mdm", "zt_net", "vpn"], nist: ["n187"] },
  "DSL": { what: "DSL delivers broadband over telephone lines. Many small sites and homes use it.", why: "Home and branch routers often have default passwords and old firmware. They can be taken over and used to spy on or redirect traffic.", how: ["Change default router passwords.", "Keep router firmware updated.", "Turn off remote management from the internet.", "Use VPN or ZTNA for business traffic."], ncsc: ["ce_sc", "ce_fw", "vpn"], nist: ["n46"] },
  "DOCSIS": { what: "DOCSIS is the standard for broadband over cable TV networks. Cable modems use it.", why: "Cable modems and routers are often unmanaged and unpatched. Compromised modems can be used to watch or redirect traffic.", how: ["Use ISP-supported, current modems.", "Change default passwords and turn off remote admin.", "Keep firmware updated.", "Protect business traffic with encryption."], ncsc: ["ce_sc", "ce_fw"], nist: ["n46"] },
  "GPON": { what: "GPON is fibre-to-the-premises technology that shares one fibre between many homes or offices. It powers many full-fibre broadband services.", why: "Shared fibre relies on encryption between the provider and your equipment. Provider equipment at your site may have weak defaults.", how: ["Treat the provider’s line as untrusted and encrypt your own traffic.", "Keep provider router admin access locked down.", "Check firmware updates are applied.", "Plan for outages."], ncsc: ["zt_net", "ce_sc"], nist: ["n53"] },
  "SONET/SDH": { what: "SONET and SDH are standards for carrying large amounts of data over fibre in telecoms core networks. Many leased lines still use them.", why: "Core links carry huge amounts of traffic, often unencrypted. A tap or outage affects many services.", how: ["Encrypt sensitive traffic over leased lines.", "Use diverse routes for critical links.", "Include telecoms providers in supply chain checks.", "Monitor link health."], ncsc: ["caf_b5", "supply_p"], nist: ["n53"] },
  "ISDN": { what: "ISDN is an older digital telephone line service. In the UK, ISDN is being switched off as networks move to IP.", why: "Old ISDN links can hide forgotten dial-in access and will stop working when retired. Alarms and lifts sometimes still depend on them.", how: ["Find any remaining ISDN lines and what uses them.", "Remove old dial-in access.", "Plan migration before the switch-off.", "Test alarms and critical lines after migration."], ncsc: ["obsolete", "s_asset"], nist: ["n53"] },
  "USB": { what: "USB connects keyboards, storage, phones and many other devices to computers. Some USB devices can act as keyboards or network cards.", why: "USB sticks can carry malware or take data out. Malicious USB devices can type commands as soon as they are plugged in.", how: ["Control which USB devices are allowed.", "Block or encrypt removable storage.", "Scan media automatically.", "Teach staff not to plug in unknown devices."], ncsc: ["periph", "ce_mal"], nist: ["n53"] },
  "RS-232": { what: "RS-232 is an old serial standard for connecting equipment such as network device consoles, industrial controllers and lab kit. It is still widely used for management.", why: "A console cable gives direct, often powerful, access to a device. Serial access may bypass network controls and logging.", how: ["Physically protect console ports.", "Use authentication on console access.", "Use secure console servers rather than loose cables.", "Log console sessions."], ncsc: ["ot", "ssa_if"], nist: ["n82"] },
  "Physical access control": { what: "Physical access control decides who can enter buildings, rooms and cabinets. It uses badges, locks, PINs and visitor procedures.", why: "Physical access can bypass many digital controls. Someone in a server room can steal, tap or tamper with equipment.", how: ["Use zones, with stronger checks for sensitive areas.", "Use individual badges and log entries.", "Escort visitors and contractors.", "Remove access promptly when people leave."], ncsc: ["caf_b2", "caf_b4"], nist: ["n116"] },
  "CCTV & intrusion detection": { what: "CCTV and intrusion detection alarms watch for unauthorised entry or tampering. They alert security staff and record evidence.", why: "Physical attacks often go unnoticed without monitoring. Recordings help investigations and discourage attackers.", how: ["Cover entrances, server rooms and cabinets.", "Make sure alerts are watched and acted on.", "Keep recordings for an agreed time and protect them.", "Treat CCTV systems as networked devices that need securing too."], ncsc: ["caf_c1", "places"], nist: ["n53"] },
  "Secure cabling & conduits": { what: "Secure cabling runs network cables through protected routes such as locked trunking or conduits. It makes tapping or cutting harder.", why: "Exposed cables in shared spaces can be tapped or damaged. Protecting them supports both confidentiality and availability.", how: ["Route sensitive cables through controlled areas.", "Use locked or sealed trunking in shared spaces.", "Label cables discreetly.", "Inspect routes periodically."], ncsc: ["caf_b5", "d_disrupt"], nist: ["n53"] },
  "Port blockers & locks": { what: "Port blockers and locks physically stop people using USB, network or other ports. They suit kiosks, public areas and sensitive devices.", why: "Open ports let anyone plug in a device in seconds. Physical blocks add a simple barrier.", how: ["Fit blockers on public and shared devices.", "Combine them with software device control.", "Keep keys controlled.", "Check fittings during routine inspections."], ncsc: ["periph", "caf_b4"], nist: ["n53"] },
  "TEMPEST / EMSEC": { what: "TEMPEST, or emanation security (EMSEC), protects against information leaking through radio or electrical signals from equipment. It is used where very sensitive information is handled.", why: "Some equipment gives off signals that could be captured and decoded from nearby. Specialist attackers may try this in high-risk settings.", how: ["Get specialist advice where it is required.", "Use approved equipment and separation distances.", "Control the space around sensitive equipment.", "Follow your sector’s official guidance."], ncsc: ["caf_b4", "d_hard"], nist: ["n53"] },
  "Fibre-tap detection": { what: "Fibre-tap detection monitors fibre links for the small signal changes caused by tapping or bending. It alerts when a link is disturbed.", why: "Fibre taps are hard to see. Detection gives warning that a link may be under attack.", how: ["Monitor optical power levels on critical links.", "Alert on sudden changes.", "Investigate unexplained signal loss.", "Encrypt data on the link as well."], ncsc: ["caf_c1", "caf_b5"], nist: ["n53"] },
  "RF monitoring & anti-jamming": { what: "RF monitoring watches the radio spectrum for jamming, rogue transmitters and interference. Anti-jamming techniques keep links working.", why: "Jamming can knock out Wi-Fi, mobile and GPS links. Rogue transmitters can be used to spy or attack.", how: ["Monitor critical radio environments.", "Use wired or diverse backups for critical links.", "Alert on jamming or unknown transmitters.", "Plan responses for loss of wireless links."], ncsc: ["caf_c1", "d_disrupt"], nist: ["n153"] },
  "Tamper-evident seals": { what: "Tamper-evident seals show if a device, case or cabinet has been opened. They are cheap and simple to check.", why: "Hardware tampering can install hidden implants. Seals make tampering visible during checks.", how: ["Seal cases and cabinets for sensitive equipment.", "Record seal numbers and check them regularly.", "Investigate broken seals.", "Check seals on deliveries from suppliers."], ncsc: ["supply_p", "caf_b4"], nist: ["n161"] },
  "QKD": { what: "Quantum key distribution (QKD) uses the physics of light to share encryption keys between two points. It needs special hardware and dedicated links.", why: "QKD is often marketed as unbreakable, but it has practical limits and cannot prove who is at the other end on its own. The NCSC says it will not support QKD for government or military use, and favours post-quantum cryptography.", how: ["Read the NCSC position before considering QKD.", "Prefer post-quantum cryptography for most needs.", "If used, combine it with other authentication.", "Treat it as a specialist, niche option."], ncsc: ["qnet", "pqc"], nist: ["ir8547"] },
  "Resilient power & diverse routes": { what: "Resilient power uses UPS units and generators to keep systems running. Diverse routes use separate cable paths and providers.", why: "Power cuts and cable damage can take services offline as surely as an attack. Resilience keeps essential services running.", how: ["Use UPS and generators for critical systems.", "Use diverse network routes and providers.", "Test failover regularly.", "Check single points of failure in supplier links."], ncsc: ["caf_b5", "d_disrupt"], nist: ["n34"] }
  };

  /* Cross-layer capabilities (the grey chips). Kept separate because a name can repeat a layer item (XDR). */
  var X = {
  "Zero Trust architecture": { what: "Zero trust is a security approach where no user, device or network is trusted by default. Every request is checked using identity, device health and context.", why: "Traditional networks trust anything inside, so one break-in can spread widely. Zero trust limits what a stolen login or infected device can reach.", how: ["Know your users, devices and services.", "Authenticate and authorise every request.", "Use policies based on risk and device health.", "Monitor users, devices and services, not just networks."], ncsc: ["zt", "zt_p", "zt_net"], nist: ["n207"] },
  "SIEM / SOAR": { what: "A SIEM collects and analyses security logs from across the organisation. SOAR automates common response steps.", why: "Attacks leave traces across many systems that are hard to link by hand. A SIEM spots patterns, and SOAR speeds up the response.", how: ["Collect logs from identity, endpoints, network and cloud.", "Build detections for your most likely threats.", "Automate simple, safe responses.", "Make sure analysts review and act on alerts."], ncsc: ["soc", "logging", "caf_c1"], nist: ["n92", "n137"] },
  "NDR": { what: "Network detection and response (NDR) analyses network traffic to spot suspicious behaviour. It works even on devices that cannot run security agents.", why: "Attackers moving inside a network create unusual traffic. NDR can catch them where endpoint tools are missing.", how: ["Place sensors where traffic between key zones can be seen.", "Include east–west traffic inside the network.", "Feed alerts into your SIEM.", "Investigate unusual connections and data transfers."], ncsc: ["caf_c1", "soc_det", "lateral"], nist: ["n94"] },
  "XDR": { what: "Extended detection and response (XDR) links data from endpoints, email, identity, network and cloud. It shows an attack as one story rather than separate alerts.", why: "Attacks cross many systems, and separate tools miss the bigger picture. XDR speeds up investigation and response.", how: ["Connect as many sources as your platform supports.", "Use automatic correlation to reduce noise.", "Practise isolating devices and disabling accounts.", "Keep people in charge of big decisions."], ncsc: ["soc", "caf_c1", "caf_c2"], nist: ["n61"] },
  "NGFW (L3–L7)": { what: "A next-generation firewall (NGFW) combines a normal firewall with application awareness and intrusion prevention. It can control traffic by app and user, not just port.", why: "Many threats use allowed ports such as 443. An NGFW can see and block them by application and behaviour.", how: ["Create rules by application and user group.", "Turn on intrusion prevention and keep it updated.", "Decide carefully what encrypted traffic to inspect.", "Patch firewalls quickly; they are prime targets."], ncsc: ["ce_fw", "netfund", "heightened"], nist: ["n41"] },
  "Threat intelligence": { what: "Threat intelligence is information about attackers, their methods and their tools. It helps you focus defences on real threats.", why: "Without it, teams guess at what to protect against. Good intelligence shows which attacks are likely and how to spot them.", how: ["Use trusted sources such as NCSC advisories and sector groups.", "Map threats to frameworks like MITRE ATT&CK.", "Turn intelligence into detections and actions.", "Share what you learn with trusted peers."], ncsc: ["soc_ti", "caf_c2", "heightened"], nist: ["n150"] },
  "Asset & config management": { what: "Asset management keeps a list of all hardware, software and services. Configuration management keeps them set up securely and spots changes.", why: "You cannot protect what you do not know you have. Unknown or drifted systems are a common way in.", how: ["Keep an up-to-date inventory with owners.", "Apply secure baseline settings.", "Detect and fix configuration drift.", "Remove unsupported systems."], ncsc: ["s_asset", "caf_a3", "ce_sc"], nist: ["n128"] },
  "Vulnerability management": { what: "Vulnerability management finds, prioritises and fixes security weaknesses in systems and software. It is a continuous process.", why: "Attackers quickly exploit known flaws, especially on internet-facing systems. Fast patching closes the most common route in.", how: ["Scan all systems regularly, including cloud.", "Fix high-risk flaws within 14 days, as Cyber Essentials requires.", "Prioritise internet-facing and actively exploited flaws.", "Track progress and exceptions."], ncsc: ["vuln", "ce_upd", "s_vuln"], nist: ["n40"] }
  };

